files.index.tpl:
@template "Shared project"
@type Card
@param title String label="Card title" required
@endtype
@section content "Content"
@param cards Card[]
@param accent Color = "#ff8068"
@endsection
@layout
<a href="demo/app.html">Next</a>
@each card in cards
<h2>{{card.title}}</h2>
@endeach
@endlayout

files.demo/app.tpl.html:
@template "Details"
@section details "Details"
@param headline String = "Details"
@endsection
@layout
<h1>{{headline}}</h1>
@each card in cards
<p>{{card.title}}</p>
@endeach
@endlayout
